referenceSolutions.javascript:
function priorityBasketPositiveProofStrip(readings) {
  const a=readings; let out=[];
  const heap=[];for(const x of a){heap.push(x);let i=heap.length-1;while(i){const p=(i-1)>>1;if(heap[p]<=heap[i])break;[heap[p],heap[i]]=[heap[i],heap[p]];i=p;}}while(heap.length){out.push(heap[0]);const last=heap.pop();if(!heap.length)break;heap[0]=last;let i=0;while(true){let j=i,l=2*i+1,r=l+1;if(l<heap.length&&heap[l]<heap[j])j=l;if(r<heap.length&&heap[r]<heap[j])j=r;if(j===i)break;[heap[i],heap[j]]=[heap[j],heap[i]];i=j;}}
  return out.filter(x=>x>0);
}

